<?php
declare(strict_types=1);if(!defined('REDFOX_SKIP_BOTAPI_ROUTER'))define('REDFOX_SKIP_BOTAPI_ROUTER',true);require_once __DIR__.'/../lib/Security.php';redfox_secure_session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/../lib/MessageTemplates.php';require_once __DIR__.'/lib/icons.php';$q=$pdo->prepare('SELECT * FROM admin WHERE username=? LIMIT 1');$q->execute([$_SESSION['user']??'']);$a=$q->fetch(PDO::FETCH_ASSOC);if(!$a){header('Location:login.php');exit;}if(($a['rule']??'')!=='administrator'){http_response_code(403);exit;}$defs=rx_message_template_definitions();$flash='';$ft='success';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{$act=(string)($_POST['action']??'save');if($act==='restore'){$q=$pdo->prepare('INSERT IGNORE INTO textbot(id_text,text) VALUES(?,?)');$n=0;foreach($defs as$k=>$d){$q->execute([$k,$d['default']]);$n+=$q->rowCount();}$flash=$n.' قالب مفقود بازسازی شد.';}else{$vals=$_POST['template']??[];if(!is_array($vals))$vals=[];$q=$pdo->prepare('INSERT INTO textbot(id_text,text) VALUES(?,?) ON DUPLICATE KEY UPDATE text=VALUES(text)');$n=0;foreach($defs as$k=>$d){if(!array_key_exists($k,$vals))continue;$v=(string)$vals[$k];if(mb_strlen($v)>10000)throw new RuntimeException('متن قالب بیش از حد طولانی است: '.$k);$q->execute([$k,$v]);$n++;}$flash=$n.' قالب ذخیره شد.';}}catch(Throwable$e){$flash=redfox_public_exception($e, 'panel/message_templates.php');$ft='error';}}
$stored=[];try{$keys=array_keys($defs);$ph=implode(',',array_fill(0,count($keys),'?'));$q=$pdo->prepare("SELECT id_text,text FROM textbot WHERE id_text IN ($ph)");$q->execute($keys);foreach($q->fetchAll(PDO::FETCH_ASSOC)as$r)$stored[$r['id_text']]=$r['text'];}catch(Throwable$e){$flash='خواندن قالب‌ها ناموفق بود: '.redfox_public_exception($e, 'panel/message_templates.php');$ft='error';}
$groups=[];foreach($defs as$k=>$d)$groups[$d['group']][$k]=$d;
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>قالب گزارش‌های نماینده</title><link rel="stylesheet" href="css/theme.css"><style>.tpl{border:1px solid var(--border-soft);border-radius:12px;padding:14px;margin:10px 0;background:var(--surface-2)}.tpl textarea{width:100%;min-height:190px;line-height:1.9}.vars{font-size:11px;color:var(--text-muted);line-height:2}.vars code{display:inline-block;margin:2px;padding:2px 5px;background:var(--accent-soft);border-radius:5px}.sticky-save{position:sticky;bottom:8px;padding:12px;background:var(--surface-1);border:1px solid var(--border-mid);border-radius:12px;display:flex;justify-content:space-between;z-index:5}</style></head><body><section id="container"><?php include'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">قالب گزارش‌ها و اعلان‌های نماینده</h1><div class="page-head__sub">این صفحه مستقل از متن‌های عمومی است و قالب‌ها را مستقیماً در دیتابیس ایجاد یا بروزرسانی می‌کند.</div></div><?php if($flash):?><div class="card <?=$ft?>"><?=htmlspecialchars($flash)?></div><?php endif;?><div class="page-guide">متغیرهای داخل آکولاد را حذف نکنید مگر اینکه آن اطلاعات را در پیام نمی‌خواهید. HTML مجاز Telegram مانند &lt;b&gt; و &lt;code&gt; قابل استفاده است.</div><form method="post"><input type="hidden" name="action" value="save"><?php foreach($groups as$group=>$items):?><div class="card"><h2><?=htmlspecialchars($group)?></h2><?php foreach($items as$k=>$d):$v=$stored[$k]??$d['default'];?><div class="tpl" id="<?=htmlspecialchars($k)?>"><h3><?=htmlspecialchars($d['title'])?></h3><div class="vars"><b>کلید:</b> <code><?=htmlspecialchars($k)?></code><br><b>متغیرها:</b> <?php foreach($d['vars'] as$var):?><code>{<?=htmlspecialchars($var)?>}</code><?php endforeach;?></div><textarea name="template[<?=htmlspecialchars($k)?>]"><?=htmlspecialchars($v,ENT_QUOTES,'UTF-8')?></textarea></div><?php endforeach;?></div><?php endforeach;?><div class="sticky-save"><a class="btn" href="textbot.php">بازگشت به متن‌های عمومی</a><button class="btn btn-primary">ذخیره همه قالب‌ها</button></div></form><form method="post" style="margin-top:12px"><input type="hidden" name="action" value="restore"><button class="btn btn-warning">بازسازی فقط قالب‌های مفقود</button></form></div></section></section></body></html>
